<?php
$products=all('produtos','nome ASC');$addresses=all('enderecos','cidade ASC');$carriers=all('transportadores','nome ASC');
$history=db()->query('SELECT f.*,e1.cidade origem,e1.uf origem_uf,e2.cidade destino,e2.uf destino_uf,t.nome transportador FROM fretes f JOIN enderecos e1 ON e1.id=f.origem_id JOIN enderecos e2 ON e2.id=f.destino_id JOIN transportadores t ON t.id=f.transportador_id ORDER BY f.id DESC LIMIT 15')->fetchAll();
?>
<div class="freight-grid"><section class="panel"><div class="panel-header"><div><h2>Novo frete</h2><p>Selecione a rota, o transportador e os produtos</p></div><span class="pill">Cálculo no servidor</span></div>
<?php if(!$products||count($addresses)<2||!$carriers):?><div class="alert alert-warning">É necessário cadastrar ao menos 1 produto, 2 endereços e 1 transportador antes de criar um frete.</div><?php endif;?>
<form method="post" class="form-grid" id="freightForm" data-km="1.20" data-kg="0.50" data-fixed="50"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="action" value="save_freight">
<div class="form-row"><label>Data do frete<input class="form-control" type="date" name="data_frete" required value="<?=date('Y-m-d')?>"></label><label>Distância estimada (km)<input class="form-control" id="distance" type="number" min="0.01" step="0.01" name="distancia_km" placeholder="Ex.: 960" required></label></div>
<div class="form-row"><label>Origem<select class="form-select" name="origem_id" required><option value="">Selecionar...</option><?php foreach($addresses as $a):?><option value="<?=$a['id']?>"><?=h($a['nome'].' - '.$a['cidade'].'/'.$a['uf'])?></option><?php endforeach;?></select></label>
<label>Destino<select class="form-select" name="destino_id" required><option value="">Selecionar...</option><?php foreach($addresses as $a):?><option value="<?=$a['id']?>"><?=h($a['nome'].' - '.$a['cidade'].'/'.$a['uf'])?></option><?php endforeach;?></select></label></div>
<label>Transportador<select class="form-select" name="transportador_id" required><option value="">Selecionar...</option><?php foreach($carriers as $c):?><option value="<?=$c['id']?>"><?=h($c['nome'])?></option><?php endforeach;?></select></label>
<div class="products-head"><b>Produtos da carga</b><button type="button" class="btn btn-outline-purple btn-sm" id="addProduct">+ Adicionar produto</button></div>
<div id="productRows"><div class="product-row"><label>Produto<select class="form-select product-select" name="produto_id[]" required><option value="">Selecionar...</option><?php foreach($products as $x):?><option value="<?=$x['id']?>" data-weight="<?=h($x['peso_unitario'])?>"><?=h($x['nome'].' ('.$x['codigo'].')')?></option><?php endforeach;?></select></label><label>Quantidade<input class="form-control product-quantity" name="quantidade_item[]" type="number" step="1" min="1" value="1" required></label><button class="btn btn-remove" type="button" aria-label="Remover produto">×</button></div></div>
<div class="hint">A distância é informada manualmente. O PHP calcula o preço com tarifa didática de R$ 1,20/km + R$ 0,50/kg + taxa fixa de R$ 50,00.</div>
